import React, { useState, useMemo, useCallback } from 'react';
import { useCart } from '../context/CartContext';
import { toast } from 'react-toastify';

const CartPanel = React.memo(() => {
    const {
        cartItems,
        orderType,
        orderNumber,
        setOrderType,
        incrementQuantity,
        decrementQuantity,
        clearCart,
        getSubtotal,
        getParcelCharges,
        getTax,
        getTotal,
    } = useCart();

    const [paymentMethod, setPaymentMethod] = useState('cash');
    const [showCustomerForm, setShowCustomerForm] = useState(false);
    const [customerDetails, setCustomerDetails] = useState({
        fullName: '',
        mobileNumber: '',
        email: '',
    });
    const [couponCode, setCouponCode] = useState('');
    const [appliedCoupon, setAppliedCoupon] = useState(null);
    const [couponLoading, setCouponLoading] = useState(false);

    // Memoize store and APIs to prevent re-creation on every render
    const { store } = useMemo(() => {
        return require('../context/AuthContext').useAuth();
    }, []);
    
    const { ordersAPI, combinedAPI, couponsAPI } = useMemo(() => {
        return require('../services/api');
    }, []);

    // Memoize final total calculation
    const finalTotal = useMemo(() => {
        const baseTotal = getTotal();
        if (appliedCoupon) {
            return baseTotal - appliedCoupon.discount;
        }
        return baseTotal;
    }, [getTotal, appliedCoupon]);

    // Apply coupon with useCallback to prevent re-creation
    const handleApplyCoupon = useCallback(async () => {
        if (!couponCode.trim()) {
            toast.error('Please enter a coupon code');
            return;
        }

        setCouponLoading(true);
        try {
            const response = await couponsAPI.validate({
                code: couponCode.trim(),
                orderAmount: getTotal(),
                storeId: store?.id || store?._id
            });

            if (response.data.success) {
                setAppliedCoupon(response.data.data);
                toast.success(`Coupon applied! You saved ₹${response.data.data.discount}`);
            }
        } catch (error) {
            const message = error.response?.data?.message || 'Invalid coupon code';
            toast.error(message);
        } finally {
            setCouponLoading(false);
        }
    }, [couponCode, getTotal, store, couponsAPI]);

    // Remove coupon with useCallback
    const handleRemoveCoupon = useCallback(() => {
        setAppliedCoupon(null);
        setCouponCode('');
        toast.info('Coupon removed');
    }, []);

    // Helper function to open PDF in new tab with auto-print dialog
    const openPDFInNewTab = (blob, filename) => {
        try {
            const url = window.URL.createObjectURL(blob);
            const newWindow = window.open(url, '_blank');

            if (newWindow) {
                newWindow.document.title = filename;

                // Auto-trigger print dialog after PDF loads
                newWindow.onload = function() {
                    setTimeout(() => {
                        newWindow.print();
                    }, 500);
                };
            } else {
                // Fallback if popup was blocked - download instead
                const link = document.createElement('a');
                link.href = url;
                link.download = filename;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            }

            // Clean up after some time
            setTimeout(() => window.URL.revokeObjectURL(url), 10000);
        } catch (error) {
            console.error('Error opening PDF:', error);
            // Removed toast - error will be caught by parent function
        }
    };

    const handleSaveAndPrint = useCallback(async () => {
        if (cartItems.length === 0) {
            toast.error('Cart is empty!');
            return;
        }

        try {
            // 1. Create Order with all details in ONE API call
            const orderPayload = {
                storeId: store?.id || store?._id,
                orderType,
                items: cartItems.map(item => ({
                    itemId: item._id,
                    itemType: 'FoodItemMaster',
                    itemName: item.itemName,
                    basePrice: item.basePrice,
                    quantity: item.quantity,
                    itemTotal: item.basePrice * item.quantity,
                    imageUrl: item.image,
                    gstPercent: 0, // No tax as per business requirement
                })),
                pricing: {
                    subtotal: getSubtotal(),
                    parcelCharges: getParcelCharges(),
                    totalTax: 0, // No tax as per business requirement
                    discount: appliedCoupon?.discount || 0,
                    grandTotal: finalTotal,
                },
                payment: {
                    method: paymentMethod === 'cash' ? 'cod' : 'online',
                    status: paymentMethod === 'cash' ? 'pending' : 'paid',
                    totalAmount: finalTotal,
                    paidAmount: paymentMethod === 'cash' ? 0 : finalTotal,
                    pendingAmount: paymentMethod === 'cash' ? finalTotal : 0,
                    transactionIds: [],
                },
                // Include coupon if applied
                ...(appliedCoupon && {
                    coupon: {
                        code: appliedCoupon.code,
                        couponId: appliedCoupon.couponId,
                        discount: appliedCoupon.discount
                    }
                }),
                // Include customer details if provided
                ...(showCustomerForm && (customerDetails.fullName || customerDetails.mobileNumber) && {
                    customerDetails: {
                        fullName: customerDetails.fullName,
                        mobileNumber: customerDetails.mobileNumber,
                        email: customerDetails.email,
                    }
                }),
            };

            const orderRes = await ordersAPI.create(orderPayload);
            
            // Validate response
            if (!(orderRes.data && (orderRes.data.success === true || orderRes.status === 201))) {
                throw new Error(orderRes.data?.message || 'Order creation failed');
            }
            
            const orderId = orderRes.data.order?._id;
            if (!orderId) {
                throw new Error('Order ID not found in response');
            }

            // 2. Generate combined Bill + KOT PDF (2 pages in one file)
            const combinedResponse = await combinedAPI.print(orderId);

            // Reset form
            clearCart();
            setCustomerDetails({ fullName: '', mobileNumber: '', email: '' });
            setAppliedCoupon(null);
            setCouponCode('');

            // Open combined PDF (Bill page 1 + KOT page 2)
            const orderNum = orderRes.data.order.orderNumber;
            openPDFInNewTab(combinedResponse.data, `Bill-KOT-${orderNum}.pdf`);

            // Toast removed - silent success
        } catch (error) {
            console.error('Order creation error:', error);
            toast.error(error.message || 'Failed to create order');
        }
    }, [
        cartItems,
        orderType,
        store,
        getSubtotal,
        getParcelCharges,
        appliedCoupon,
        finalTotal,
        paymentMethod,
        showCustomerForm,
        customerDetails,
        ordersAPI,
        combinedAPI,
        clearCart,
        openPDFInNewTab
    ]);

    return (
        <aside className="w-[450px] bg-white dark:bg-slate-900 border-l border-slate-200 dark:border-slate-800 flex flex-col shrink-0">
            {/* Order Type Selection - Compact */}
            <div className="p-3 grid grid-cols-2 gap-2 shrink-0">
                <button
                    onClick={() => setOrderType('dine-in')}
                    className={`py-1.5 px-3 rounded-lg font-semibold flex items-center justify-center gap-1.5 text-xs transition-colors ${
                        orderType === 'dine-in'
                            ? 'bg-primary text-white shadow-sm shadow-primary/20'
                            : 'bg-slate-100 dark:bg-slate-800 text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-700'
                    }`}
                >
                    <span className="material-icons-round text-sm">restaurant</span>
                    <span className="uppercase">Dine In</span>
                </button>
                <button
                    onClick={() => setOrderType('pickup')}
                    className={`py-1.5 px-3 rounded-lg font-semibold flex items-center justify-center gap-1.5 text-xs transition-colors ${
                        orderType === 'pickup'
                            ? 'bg-primary text-white shadow-sm shadow-primary/20'
                            : 'bg-slate-100 dark:bg-slate-800 text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-700'
                    }`}
                >
                    <span className="material-icons-round text-sm">shopping_bag</span>
                    <span className="uppercase">Pickup</span>
                </button>
            </div>

            {/* Order Header */}
            <div className="px-4 pb-2 border-b border-slate-100 dark:border-slate-800 flex justify-between items-end shrink-0">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">
                    Current Order #{orderNumber}
                </span>
                {cartItems.length > 0 && (
                    <button
                        onClick={clearCart}
                        className="text-primary text-xs font-bold flex items-center gap-1 hover:text-primary/80 transition-colors"
                    >
                        <span className="material-icons-round text-sm">delete_outline</span> CLEAR ALL
                    </button>
                )}
            </div>

            {/* Cart Items */}
            <div className="flex-1 overflow-y-auto px-4 py-2 space-y-4">
                {cartItems.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-slate-400">
                        <span className="material-icons-round text-5xl mb-2">shopping_cart</span>
                        <p className="text-sm">No items in cart</p>
                    </div>
                ) : (
                    cartItems.map((item) => (
                        <div key={item._id} className="flex items-center gap-3">
                            <div className="flex-1">
                                <div className="flex justify-between">
                                    <h4 className="font-bold text-base text-wrap">{item.itemName}</h4>
                                    <span className="font-bold text-base">
                                        ₹{(item.basePrice * item.quantity).toFixed(2)}
                                    </span>
                                </div>
                                <div className="flex items-center justify-between mt-2">
                                    <div className="flex items-center bg-slate-100 dark:bg-slate-800 rounded-lg p-1">
                                        <button
                                            onClick={() => decrementQuantity(item._id)}
                                            className="w-8 h-8 flex items-center justify-center text-slate-500 hover:text-primary"
                                        >
                                            <span className="material-icons-round text-base">remove</span>
                                        </button>
                                        <span className="px-3 text-sm font-bold">{item.quantity}</span>
                                        <button
                                            onClick={() => incrementQuantity(item._id)}
                                            className="w-8 h-8 flex items-center justify-center text-slate-500 hover:text-primary"
                                        >
                                            <span className="material-icons-round text-base">add</span>
                                        </button>
                                    </div>
                                    <span className="text-xs text-slate-400">
                                        ₹{item.basePrice.toFixed(2)} each
                                    </span>
                                </div>
                            </div>
                        </div>
                    ))
                )}
            </div>

            {/* Billing Section - Simplified */}
            <div className="p-3 bg-slate-50 dark:bg-slate-800/50 border-t border-slate-200 dark:border-slate-800 shrink-0">
                    {/* Only show breakdown if there are charges or discounts and items exist */}
                    {cartItems.length > 0 && ((orderType === 'pickup' && getParcelCharges() > 0) || appliedCoupon) ? (
                        <div className="space-y-1.5 mb-3 text-xs">
                            {orderType === 'pickup' && getParcelCharges() > 0 && (
                                <div className="flex justify-between text-slate-500 dark:text-slate-400">
                                    <span>Parcel Charges</span>
                                    <span>₹{getParcelCharges().toFixed(2)}</span>
                                </div>
                            )}
                            {appliedCoupon && (
                                <div className="flex justify-between items-center text-green-600 dark:text-green-400">
                                    <div className="flex items-center gap-1">
                                        <span className="material-icons-round text-xs">local_offer</span>
                                        <span>Coupon ({appliedCoupon.code})</span>
                                    </div>
                                    <div className="flex items-center gap-1">
                                        <span>-₹{appliedCoupon.discount.toFixed(2)}</span>
                                        <button
                                            onClick={handleRemoveCoupon}
                                            className="text-red-500 hover:text-red-700"
                                        >
                                            <span className="material-icons-round text-xs">close</span>
                                        </button>
                                    </div>
                                </div>
                            )}
                        </div>
                    ) : null}

                    {/* Customer Details Icon & Total Amount */}
                    <div className="flex justify-between items-center py-2 border-t border-slate-200 dark:border-slate-700 mb-3">
                        <button
                            onClick={() => setShowCustomerForm(!showCustomerForm)}
                            className="group relative p-2 rounded-lg bg-slate-100 dark:bg-slate-800 hover:bg-primary hover:text-white transition-all duration-200"
                            title="Customer Details & Coupon"
                        >
                            <span className="material-icons-round text-xl text-slate-600 dark:text-slate-300 group-hover:text-white transition-colors">
                                person_add
                            </span>
                            {(customerDetails.fullName || customerDetails.mobileNumber || appliedCoupon) && (
                                <span className="absolute -top-1 -right-1 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></span>
                            )}
                        </button>

                        <div className="flex flex-col items-end">
                            <span className="text-xs text-slate-500 dark:text-slate-400">Total Amount</span>
                            <span className="font-bold text-xl text-primary">
                                ₹{finalTotal.toFixed(2)}
                            </span>
                        </div>
                    </div>

                    {/* Customer Details & Coupon Section - Collapsible */}
                    <div className="mb-3">

                        {showCustomerForm && (
                            <div className="mt-2 space-y-2 p-3 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-700 shadow-lg">
                                <div>
                                    <label className="text-xs font-semibold text-slate-600 dark:text-slate-400 mb-1.5 block flex items-center gap-1">
                                        <span className="material-icons-round text-sm">person</span>
                                        Customer Information
                                    </label>
                                    <div className="space-y-1.5">
                                        <input
                                            type="text"
                                            placeholder="Customer Name"
                                            value={customerDetails.fullName}
                                            onChange={(e) => setCustomerDetails({ ...customerDetails, fullName: e.target.value })}
                                            className="w-full px-2.5 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-xs outline-none focus:ring-2 focus:ring-primary"
                                        />
                                        <input
                                            type="tel"
                                            placeholder="Mobile Number"
                                            value={customerDetails.mobileNumber}
                                            onChange={(e) => setCustomerDetails({ ...customerDetails, mobileNumber: e.target.value })}
                                            className="w-full px-2.5 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-xs outline-none focus:ring-2 focus:ring-primary"
                                        />
                                        <input
                                            type="email"
                                            placeholder="Email (Optional)"
                                            value={customerDetails.email}
                                            onChange={(e) => setCustomerDetails({ ...customerDetails, email: e.target.value })}
                                            className="w-full px-2.5 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-xs outline-none focus:ring-2 focus:ring-primary"
                                        />
                                    </div>
                                </div>

                                <div className="border-t border-slate-200 dark:border-slate-700 pt-2">
                                    <label className="text-xs font-semibold text-slate-600 dark:text-slate-400 mb-1.5 block flex items-center gap-1">
                                        <span className="material-icons-round text-sm">local_offer</span>
                                        Apply Coupon
                                    </label>
                                    {!appliedCoupon ? (
                                        <div className="flex gap-2">
                                            <input
                                                type="text"
                                                placeholder="Enter coupon code"
                                                value={couponCode}
                                                onChange={(e) => setCouponCode(e.target.value.toUpperCase())}
                                                onKeyPress={(e) => e.key === 'Enter' && handleApplyCoupon()}
                                                className="flex-1 px-2.5 py-1.5 text-xs rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 outline-none focus:ring-2 focus:ring-primary"
                                                disabled={couponLoading}
                                            />
                                            <button
                                                onClick={handleApplyCoupon}
                                                disabled={couponLoading || !couponCode.trim()}
                                                className="px-3 py-1.5 bg-primary text-white text-xs font-semibold rounded-lg hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                                            >
                                                {couponLoading ? 'Applying...' : 'Apply'}
                                            </button>
                                        </div>
                                    ) : (
                                        <div className="flex items-center justify-between p-1.5 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-lg">
                                            <div className="flex items-center gap-1.5 text-green-600 dark:text-green-400">
                                                <span className="material-icons-round text-sm">check_circle</span>
                                                <span className="text-xs font-medium">{appliedCoupon.code} Applied</span>
                                            </div>
                                            <button
                                                onClick={handleRemoveCoupon}
                                                className="text-red-500 hover:text-red-700 p-0.5"
                                            >
                                                <span className="material-icons-round text-sm">close</span>
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Payment Method - Compact */}
                    <div className="grid grid-cols-2 gap-2 mb-3">
                        <button
                            onClick={() => setPaymentMethod('cash')}
                            className={`py-2 rounded-lg flex items-center justify-center gap-1.5 transition-colors ${
                                paymentMethod === 'cash'
                                    ? 'bg-primary text-white'
                                    : 'bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 hover:bg-slate-50'
                            }`}
                        >
                            <span className={`material-icons-round text-sm ${paymentMethod === 'cash' ? 'text-white' : 'text-slate-400'}`}>payments</span>
                            <span className="text-xs font-semibold">CASH</span>
                        </button>
                        <button
                            onClick={() => setPaymentMethod('card')}
                            className={`py-2 rounded-lg flex items-center justify-center gap-1.5 transition-colors ${
                                paymentMethod === 'card'
                                    ? 'bg-primary text-white'
                                    : 'bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 hover:bg-slate-50'
                            }`}
                        >
                            <span className={`material-icons-round text-sm ${paymentMethod === 'card' ? 'text-white' : 'text-slate-400'}`}>credit_card</span>
                            <span className="text-xs font-semibold">CARD/UPI</span>
                        </button>
                    </div>

                    {/* Action Buttons - Compact */}
                    <div className="flex flex-col gap-2">
                        <button
                            onClick={handleSaveAndPrint}
                            disabled={cartItems.length === 0}
                            className={`w-full py-3 rounded-xl font-bold text-sm flex items-center justify-center gap-2 shadow-lg transition-all ${
                                cartItems.length === 0
                                    ? 'bg-slate-300 dark:bg-slate-700 text-slate-500 dark:text-slate-400 cursor-not-allowed'
                                    : 'bg-primary text-white shadow-primary/20 hover:bg-primary/90 active:scale-[0.98]'
                            }`}
                        >
                            <span className="material-icons-round text-lg">print</span>
                            SAVE &amp; PRINT
                        </button>
                        {cartItems.length > 0 && (
                            <button
                                onClick={clearCart}
                                className="w-full bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-200 py-2 rounded-lg font-semibold text-xs hover:bg-slate-300 transition-colors"
                            >
                                Clear Cart
                            </button>
                        )}
                    </div>
                </div>
        </aside>
    );
});

CartPanel.displayName = 'CartPanel';

export default CartPanel;
